const input=$input.first()?.json ?? {};
const raw=input.body && input.headers ? input.body : input;
const allowed=new Set(['crm-overview','crm-leads','crm-follow-ups','growth-funnel','customer-insights','automation-runs']);
const jobId=String(raw.jobId??'');
const rowVersion=Number(raw.rowVersion??0);
const dataset=String(raw.dataset??'');
const generatedAt=String(raw.generatedAt??'');
const valid=/^[0-9a-f-]{36}$/i.test(jobId)&&Number.isInteger(rowVersion)&&rowVersion>0&&allowed.has(dataset)&&Number.isFinite(Date.parse(generatedAt));
if(!valid) throw new Error('EXPORT_INPUT_INVALID');
return [{json:{
  jobId,rowVersion,dataset,generatedAt,
  startedAt:new Date().toISOString(),
  correlationId:String(raw.correlationId??''),
  requestId:String(raw.requestId??'')
}}];

