const data=$('ดึงข้อมูล Export').item.json;
const created=$json;
const spreadsheetId=String(created.spreadsheetId??'');
if(!spreadsheetId) throw new Error('GOOGLE_SHEET_ID_MISSING');
const sheets=Array.isArray(created.sheets)?created.sheets:[];
const overviewSheetId=Number(sheets[0]?.properties?.sheetId??0);
const dataSheetId=Number(sheets[1]?.properties?.sheetId??1);
const columns=Array.isArray(data.columns)?data.columns.map(String):[];
const rows=Array.isArray(data.rows)?data.rows:[];
const overview=Array.isArray(data.overview)?data.overview:[];
const overviewValues=[['รายการ','ค่า'],...overview.map(x=>[String(x.label??''),x.value??''])];
const dataValues=[columns,...rows.map(row=>columns.map(col=>row?.[col]??''))];
return [{json:{
  spreadsheetId,
  spreadsheetUrl:'https://docs.google.com/spreadsheets/d/'+spreadsheetId+'/edit',
  overviewSheetId,dataSheetId,overviewValues,dataValues,
  dataColumnCount:Math.max(1,columns.length),
  dataRowCount:dataValues.length,
  title:String(data.fileName??data.title??'CCPun Export')
}}];

