={{ (() => {
  const s=$('เตรียมค่า Sheet').item.json;
  return {requests:[
    {updateSpreadsheetProperties:{properties:{timeZone:'Asia/Bangkok',locale:'th_TH'},fields:'timeZone,locale'}},
    {updateSheetProperties:{properties:{sheetId:s.overviewSheetId,gridProperties:{frozenRowCount:1}},fields:'gridProperties.frozenRowCount'}},
    {updateSheetProperties:{properties:{sheetId:s.dataSheetId,gridProperties:{frozenRowCount:1}},fields:'gridProperties.frozenRowCount'}},
    {repeatCell:{range:{sheetId:s.overviewSheetId,startRowIndex:0,endRowIndex:1},cell:{userEnteredFormat:{textFormat:{bold:true}}},fields:'userEnteredFormat.textFormat.bold'}},
    {repeatCell:{range:{sheetId:s.dataSheetId,startRowIndex:0,endRowIndex:1},cell:{userEnteredFormat:{textFormat:{bold:true}}},fields:'userEnteredFormat.textFormat.bold'}},
    {setBasicFilter:{filter:{range:{sheetId:s.dataSheetId,startRowIndex:0,endRowIndex:Math.max(1,s.dataRowCount),startColumnIndex:0,endColumnIndex:s.dataColumnCount}}}},
    {autoResizeDimensions:{dimensions:{sheetId:s.overviewSheetId,dimension:'COLUMNS',startIndex:0,endIndex:2}}},
    {autoResizeDimensions:{dimensions:{sheetId:s.dataSheetId,dimension:'COLUMNS',startIndex:0,endIndex:s.dataColumnCount}}}
  ]};
})() }}

